const emptyFeatures=()=>Object.fromEntries(features.map(([key])=>[key,true])) as Features
const currencyScale=(currency:string)=>10**new Intl.NumberFormat('en',{style:'currency',currency}).resolvedOptions().maximumFractionDigits!
const price=(minor:number,currency:string)=>new Intl.NumberFormat('en',{style:'currency',currency}).format(minor/currencyScale(currency))
const initialMetadata=():Metadata=>({name:'',customer_access_policy:'retain_access',contract_reference:'',billing_mode:'wholesale',contract_starts_at:new Date().toISOString(),contract_ends_at:new Date(Date.now()+365*86400000).toISOString()})
function metadata(r:Metadata):Metadata{return {name:r.name,customer_access_policy:r.customer_access_policy,contract_reference:r.contract_reference,billing_mode:r.billing_mode,contract_starts_at:r.contract_starts_at,contract_ends_at:r.contract_ends_at}}
function Pager({next,history,cursor,setCursor,setHistory}:{next:string|null;history:string[];cursor:string;setCursor:(v:string)=>void;setHistory:(v:string[])=>void}){return <div className="sa-pagination"><Button type="button" variant="outline" disabled={!history.length} onClick={()=>{setCursor(history.at(-1)||'');setHistory(history.slice(0,-1))}}>Previous page</Button><span>Up to 25 per page</span><Button type="button" variant="outline" disabled={!next} onClick={()=>{setHistory([...history,cursor]);setCursor(next||'')}}>Next page</Button></div>}
function Table({label,children,className=""}:{label:string;children:React.ReactNode;className?:string}){return <div className={"sa-table-scroll "+className} tabIndex={0} role="region" aria-label={label}><table className="sa-table">{children}</table></div>}
function Policy({value}:{value:Metadata}){return <Notice>{value.customer_access_policy==='retain_access'?'Customers keep their existing workspace access when this reseller is suspended or its contract expires.':'Suspending this reseller or letting its contract expire will suspend every linked customer workspace.'} Customer data is retained. Reseller commercial administration and new assignments require approval and a current contract.</Notice>}
function MetadataFields({value,onChange}:{value:Metadata;onChange:(v:Metadata)=>void}){return <><Field label="Organization name"><Input value={value.name} onChange={e=>onChange({...value,name:e.target.value})} required minLength={2} maxLength={100}/></Field><div className="sa-agreement-fields"><Field label="Contract reference"><Input value={value.contract_reference} onChange={e=>onChange({...value,contract_reference:e.target.value})} required minLength={3} maxLength={200}/></Field><Field label="Commercial billing mode"><NativeSelect aria-label="Commercial billing mode" value={value.billing_mode} onChange={e=>onChange({...value,billing_mode:e.target.value as Metadata['billing_mode']})}><option value="wholesale">Wholesale</option><option value="managed_rebilling">Managed rebilling</option></NativeSelect><small>Contract metadata. Payment collection and settlement are not configured here.</small></Field><Field label="Contract starts (your local time)"><Input type="datetime-local" required value={localDate(value.contract_starts_at)} onChange={e=>{if(e.target.value)onChange({...value,contract_starts_at:new Date(e.target.value).toISOString()})}}/></Field><Field label="Contract ends (your local time)"><Input type="datetime-local" required min={localDate(value.contract_starts_at)} value={localDate(value.contract_ends_at)} onChange={e=>{if(e.target.value)onChange({...value,contract_ends_at:new Date(e.target.value).toISOString()})}}/></Field></div><Field label="Customer access during reseller suspension or contract expiry"><NativeSelect aria-label="Customer access during reseller suspension or contract expiry" value={value.customer_access_policy} onChange={e=>onChange({...value,customer_access_policy:e.target.value as Metadata['customer_access_policy']})}><option value="retain_access">Retain customer access</option><option value="suspend_access">Suspend linked customer access</option></NativeSelect></Field><Policy value={value}/></>}
function LimitFields({value,onChange,upstream,title}:{value:Limits;onChange:(v:Limits)=>void;upstream?:Limits;title:string}){return <section className="sa-commercial-section"><h2>{title}</h2><p>Zero blocks growth. Blank means no ceiling at this level. Existing resources are retained when limits fall.</p><div className="sa-limit-fields">{meters.map(([key,label,hint])=><Field key={key} label={label+' ceiling'}><Input type="number" min={0} max={upstream?.[key]??1000000000} required={upstream?.[key]!=null} step={1} value={value[key]??''} placeholder="No ceiling" onChange={e=>onChange({...value,[key]:e.target.value===''?null:Number(e.target.value)})}/><small>{upstream&&'Upstream: '+limit(upstream[key])+'. '}{hint}</small></Field>)}</div></section>}
function FeatureFields({value,onChange,upstream}:{value:Features;onChange:(v:Features)=>void;upstream?:Features}){return <section className="sa-commercial-section"><h2>Included modules</h2><div className="sa-feature-fields">{features.map(([key,label])=><label className="sa-checkbox" key={key}><input type="checkbox" checked={value[key]} disabled={upstream&&!upstream[key]&&!value[key]} onChange={e=>onChange({...value,[key]:e.target.checked})}/>{label}{upstream&&!upstream[key]&&<small>Unavailable upstream</small>}</label>)}</div></section>}
