function GrantSummary({value}:{value:Grant}){return <><dl className="sa-facts"><dt>Maximum customer workspaces</dt><dd>{limit(value.max_workspaces)}</dd><dt>Maximum customer trial</dt><dd>{value.trial_days_max} days</dd><dt>Platform plan version</dt><dd>{value.platform_plan_version}</dd></dl><ResourceSummary value={value.limits} aggregate={value.aggregate_limits}/><ModuleSummary value={value.features}/></>}
