 function choosePlan(id:string){confirmDiscard('Changing the upstream plan clears this grant’s per-workspace limits and modules. Select and review an exact version.',()=>{onChange({...value,platform_plan_id:id,platform_plan_version:0,limits:emptyLimits(),features:emptyFeatures()});setBefore(null);setHistory([])})}
