 const [search,setSearch]=useState(''),[query,setQuery]=useState(''),[status,setStatus]=useState('all'),[cursor,setCursor]=useState(''),[history,setHistory]=useState<string[]>([]),saved=useData<Page<Reseller>>('/resellers?search='+encodeURIComponent(query)+'&status='+status+(cursor?'&cursor='+cursor:''))
